// Package codex implements the Agent interface for OpenAI's Codex CLI.
package codex

import (
	"context"
	"errors"
	"fmt"
	"os"
	"path/filepath"

	"github.com/entireio/cli/cmd/entire/cli/agent"
	"github.com/entireio/cli/cmd/entire/cli/agent/types"
)

//nolint:gochecknoinits // Agent self-registration is the intended pattern
func init() {
	agent.Register(agent.AgentNameCodex, NewCodexAgent)
}

// CodexAgent implements the Agent interface for OpenAI's Codex CLI.
//
//nolint:revive // CodexAgent is clearer than Agent in this context
type CodexAgent struct{}

// NewCodexAgent creates a new Codex agent instance.
func NewCodexAgent() agent.Agent {
	return &CodexAgent{}
}

// Name returns the agent registry key.
func (c *CodexAgent) Name() types.AgentName {
	return agent.AgentNameCodex
}

// Type returns the agent type identifier.
func (c *CodexAgent) Type() types.AgentType {
	return agent.AgentTypeCodex
}

// Description returns a human-readable description.
func (c *CodexAgent) Description() string {
	return "Codex - OpenAI's CLI coding agent"
}

// IsPreview returns true because this is a new integration.
func (c *CodexAgent) IsPreview() bool { return true }

// DetectPresence checks if Codex is configured in the repository.
func (c *CodexAgent) DetectPresence(ctx context.Context) (bool, error) {
	return c.AreHooksInstalled(ctx), nil
}

// GetSessionID extracts the session ID from hook input.
func (c *CodexAgent) GetSessionID(input *agent.HookInput) string {
	return input.SessionID
}

// resolveCodexHome returns the Codex home directory (CODEX_HOME or ~/.codex).
func resolveCodexHome() (string, error) {
	if codexHome := os.Getenv("CODEX_HOME"); codexHome != "" {
		return codexHome, nil
	}
	homeDir, err := os.UserHomeDir()
	if err != nil {
		return "", fmt.Errorf("failed to get home directory: %w", err)
	}
	return filepath.Join(homeDir, ".codex"), nil
}

// GetSessionDir returns the directory where Codex stores session transcripts.
// Codex stores transcripts (rollout files) in its home directory.
func (c *CodexAgent) GetSessionDir(_ string) (string, error) {
	if override := os.Getenv("ENTIRE_TEST_CODEX_SESSION_DIR"); override != "" {
		return override, nil
	}
	return resolveCodexHome()
}

// ResolveSessionFile returns the path to a Codex session transcript file.
// Codex provides the transcript path directly in hook payloads as an absolute path.
// When only a session ID is available, we construct a best-effort path.
func (c *CodexAgent) ResolveSessionFile(sessionDir, agentSessionID string) string {
	if filepath.IsAbs(agentSessionID) {
		return agentSessionID
	}
	if sessionDir != "" {
		return filepath.Join(sessionDir, agentSessionID+".jsonl")
	}
	return agentSessionID
}

// ProtectedDirs returns directories that Codex uses for config/state.
func (c *CodexAgent) ProtectedDirs() []string { return []string{".codex"} }

// ReadSession reads a session from Codex's storage (JSONL rollout file).
func (c *CodexAgent) ReadSession(input *agent.HookInput) (*agent.AgentSession, error) {
	if input.SessionRef == "" {
		return nil, errors.New("session reference (transcript path) is required")
	}

	data, err := os.ReadFile(input.SessionRef)
	if err != nil {
		return nil, fmt.Errorf("failed to read transcript: %w", err)
	}

	startTime, err := parseSessionStartTime(data)
	if err != nil {
		return nil, fmt.Errorf("failed to parse session start time: %w", err)
	}

	// Extract modified files from the rollout transcript (best-effort, deduplicated).
	var modifiedFiles []string
	seen := make(map[string]struct{})
	for _, lineData := range splitJSONL(data) {
		for _, f := range extractFilesFromLine(lineData) {
			if _, exists := seen[f]; !exists {
				seen[f] = struct{}{}
				modifiedFiles = append(modifiedFiles, f)
			}
		}
	}

	return &agent.AgentSession{
		SessionID:     input.SessionID,
		AgentName:     c.Name(),
		SessionRef:    input.SessionRef,
		StartTime:     startTime,
		NativeData:    data,
		ModifiedFiles: modifiedFiles,
	}, nil
}

// WriteSession writes a session to Codex's storage (JSONL rollout file).
func (c *CodexAgent) WriteSession(_ context.Context, session *agent.AgentSession) error {
	if session == nil {
		return errors.New("session is nil")
	}

	if session.AgentName != "" && session.AgentName != c.Name() {
		return fmt.Errorf("session belongs to agent %q, not %q", session.AgentName, c.Name())
	}

	if session.SessionRef == "" {
		return errors.New("session reference (transcript path) is required")
	}

	if len(session.NativeData) == 0 {
		return errors.New("session has no native data to write")
	}

	if err := os.WriteFile(session.SessionRef, session.NativeData, 0o600); err != nil {
		return fmt.Errorf("failed to write transcript: %w", err)
	}

	return nil
}

// FormatResumeCommand returns the command to resume a Codex session.
func (c *CodexAgent) FormatResumeCommand(sessionID string) string {
	return "codex resume " + sessionID
}

// ReadTranscript reads the raw JSONL transcript bytes for a session.
func (c *CodexAgent) ReadTranscript(sessionRef string) ([]byte, error) {
	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
	if err != nil {
		return nil, fmt.Errorf("failed to read transcript: %w", err)
	}
	return data, nil
}

// ChunkTranscript splits a JSONL transcript at line boundaries.
func (c *CodexAgent) ChunkTranscript(_ context.Context, content []byte, maxSize int) ([][]byte, error) {
	chunks, err := agent.ChunkJSONL(content, maxSize)
	if err != nil {
		return nil, fmt.Errorf("failed to chunk JSONL transcript: %w", err)
	}
	return chunks, nil
}

// ReassembleTranscript concatenates JSONL chunks with newlines.
func (c *CodexAgent) ReassembleTranscript(chunks [][]byte) ([]byte, error) {
	return agent.ReassembleJSONL(chunks), nil
}

package codex

import (
	"bufio"
	"bytes"
	"encoding/json"
	"errors"
	"fmt"
	"io"
	"os"
	"regexp"
	"strings"
	"time"

	"github.com/entireio/cli/cmd/entire/cli/agent"
)

// Compile-time interface assertions.
var (
	_ agent.TranscriptAnalyzer = (*CodexAgent)(nil)
	_ agent.TokenCalculator    = (*CodexAgent)(nil)
	_ agent.PromptExtractor    = (*CodexAgent)(nil)
)

// rolloutLine is the top-level JSONL line structure in Codex rollout files.
type rolloutLine struct {
	Timestamp string          `json:"timestamp"`
	Type      string          `json:"type"` // "session_meta", "response_item", "event_msg", "turn_context"
	Payload   json.RawMessage `json:"payload"`
}

// sessionMetaPayload is the payload for type="session_meta" lines.
type sessionMetaPayload struct {
	ID        string `json:"id"`
	Timestamp string `json:"timestamp"`
}

// responseItemPayload is the payload for type="response_item" lines.
type responseItemPayload struct {
	Type    string          `json:"type"` // "message", "custom_tool_call", "custom_tool_call_output", "local_shell_call", "function_call", etc.
	Role    string          `json:"role,omitempty"`
	Name    string          `json:"name,omitempty"`
	Input   string          `json:"input,omitempty"`   // apply_patch input (plain text, not JSON)
	Content json.RawMessage `json:"content,omitempty"` // for messages
}

// contentItem is a single content block in a message.
type contentItem struct {
	Type string `json:"type"` // "input_text", "output_text"
	Text string `json:"text"`
}

// eventMsgPayload is the payload for type="event_msg" lines.
type eventMsgPayload struct {
	Type string          `json:"type"` // "token_count", "task_started", "user_message", "agent_message", "task_complete"
	Info json.RawMessage `json:"info,omitempty"`
}

// tokenCountInfo contains token usage data from event_msg.token_count.
type tokenCountInfo struct {
	TotalTokenUsage *tokenUsageData `json:"total_token_usage,omitempty"`
}

// tokenUsageData maps to Codex's token usage fields.
type tokenUsageData struct {
	InputTokens           int `json:"input_tokens"`
	CachedInputTokens     int `json:"cached_input_tokens"`
	OutputTokens          int `json:"output_tokens"`
	ReasoningOutputTokens int `json:"reasoning_output_tokens"`
	TotalTokens           int `json:"total_tokens"`
}

// applyPatchFileRegex extracts file paths from apply_patch input.
// Matches "*** Add File: <path>", "*** Update File: <path>", "*** Delete File: <path>"
var applyPatchFileRegex = regexp.MustCompile(`\*\*\* (?:Add|Update|Delete) File: (.+)`)

// GetTranscriptPosition returns the current line count of a Codex rollout transcript.
func (c *CodexAgent) GetTranscriptPosition(path string) (int, error) {
	if path == "" {
		return 0, nil
	}

	file, err := os.Open(path) //nolint:gosec // Path comes from agent hook input
	if err != nil {
		if os.IsNotExist(err) {
			return 0, nil
		}
		return 0, fmt.Errorf("failed to open transcript: %w", err)
	}
	defer file.Close()

	reader := bufio.NewReader(file)
	lineCount := 0
	for {
		line, readErr := reader.ReadBytes('\n')
		if readErr != nil {
			if readErr == io.EOF {
				if len(line) > 0 {
					lineCount++
				}
				break
			}
			return 0, fmt.Errorf("failed to read transcript: %w", readErr)
		}
		lineCount++
	}
	return lineCount, nil
}

// ExtractModifiedFilesFromOffset extracts files modified since a given line offset.
func (c *CodexAgent) ExtractModifiedFilesFromOffset(path string, startOffset int) (files []string, currentPosition int, err error) {
	if path == "" {
		return nil, 0, nil
	}

	file, openErr := os.Open(path) //nolint:gosec // Path comes from agent hook input
	if openErr != nil {
		return nil, 0, fmt.Errorf("failed to open transcript: %w", openErr)
	}
	defer file.Close()

	reader := bufio.NewReader(file)
	seen := make(map[string]struct{})
	lineNum := 0

	for {
		lineData, readErr := reader.ReadBytes('\n')
		if readErr != nil && readErr != io.EOF {
			return nil, 0, fmt.Errorf("failed to read transcript: %w", readErr)
		}

		if len(lineData) > 0 {
			lineNum++
			if lineNum > startOffset {
				for _, f := range extractFilesFromLine(lineData) {
					if _, ok := seen[f]; !ok {
						seen[f] = struct{}{}
						files = append(files, f)
					}
				}
			}
		}

		if readErr == io.EOF {
			break
		}
	}

	return files, lineNum, nil
}

// extractFilesFromLine extracts modified file paths from a single rollout JSONL line.
func extractFilesFromLine(lineData []byte) []string {
	var line rolloutLine
	if json.Unmarshal(lineData, &line) != nil {
		return nil
	}

	if line.Type != "response_item" {
		return nil
	}

	var payload responseItemPayload
	if json.Unmarshal(line.Payload, &payload) != nil {
		return nil
	}

	// apply_patch custom tool calls contain file paths in the input text
	if payload.Type == "custom_tool_call" && payload.Name == "apply_patch" {
		return extractFilesFromApplyPatch(payload.Input)
	}

	return nil
}

// extractFilesFromApplyPatch parses apply_patch input for file paths.
// Format: "*** Add File: <path>" or "*** Update File: <path>" or "*** Delete File: <path>"
func extractFilesFromApplyPatch(input string) []string {
	matches := applyPatchFileRegex.FindAllStringSubmatch(input, -1)
	var files []string
	seen := make(map[string]struct{})
	for _, m := range matches {
		path := strings.TrimSpace(m[1])
		if path != "" {
			if _, ok := seen[path]; !ok {
				seen[path] = struct{}{}
				files = append(files, path)
			}
		}
	}
	return files
}

// CalculateTokenUsage computes token usage from the transcript starting at the given line offset.
// Codex reports cumulative total_token_usage, so we compute the delta between the last
// token_count at/before the offset and the last token_count after the offset.
func (c *CodexAgent) CalculateTokenUsage(transcriptData []byte, fromOffset int) (*agent.TokenUsage, error) {
	var baselineUsage *tokenUsageData // last token_count at or before offset
	var lastUsage *tokenUsageData     // last token_count after offset
	apiCalls := 0
	lineNum := 0

	for _, lineData := range splitJSONL(transcriptData) {
		lineNum++

		var line rolloutLine
		if json.Unmarshal(lineData, &line) != nil {
			continue
		}
		if line.Type != "event_msg" {
			continue
		}
		var evt eventMsgPayload
		if json.Unmarshal(line.Payload, &evt) != nil {
			continue
		}
		if evt.Type != "token_count" || len(evt.Info) == 0 {
			continue
		}
		var info tokenCountInfo
		if json.Unmarshal(evt.Info, &info) != nil || info.TotalTokenUsage == nil {
			continue
		}

		if lineNum <= fromOffset {
			baselineUsage = info.TotalTokenUsage
		} else {
			lastUsage = info.TotalTokenUsage
			apiCalls++
		}
	}

	if lastUsage == nil {
		return nil, nil //nolint:nilnil // no usage data found
	}

	// Subtract baseline to get the delta for this checkpoint range
	result := &agent.TokenUsage{
		InputTokens:     lastUsage.InputTokens,
		CacheReadTokens: lastUsage.CachedInputTokens,
		OutputTokens:    lastUsage.OutputTokens + lastUsage.ReasoningOutputTokens,
		APICallCount:    apiCalls,
	}
	if baselineUsage != nil {
		result.InputTokens -= baselineUsage.InputTokens
		result.CacheReadTokens -= baselineUsage.CachedInputTokens
		result.OutputTokens -= baselineUsage.OutputTokens + baselineUsage.ReasoningOutputTokens
	}

	return result, nil
}

// ExtractPrompts returns user prompts from the transcript starting at the given offset.
func (c *CodexAgent) ExtractPrompts(sessionRef string, fromOffset int) ([]string, error) {
	data, err := os.ReadFile(sessionRef) //nolint:gosec // Path comes from agent hook input
	if err != nil {
		if os.IsNotExist(err) {
			return nil, nil
		}
		return nil, fmt.Errorf("failed to read transcript: %w", err)

	// Count sessions to restore
	totalSessions := len(summary.Sessions)
	if totalSessions > 1 {
		fmt.Fprintf(w, "Restoring %d sessions from checkpoint:\n", totalSessions)
	}

	// Restore all sessions (oldest to newest, using 0-based indexing)
	var restored []RestoredSession
	for i := range totalSessions {
		content, readErr := reader.ReadSessionContent(ctx, point.CheckpointID, i)
		if readErr != nil {
			if !errors.Is(readErr, cpkg.ErrNoTranscript) {
				fmt.Fprintf(errW, "  Warning: failed to read session %d: %v\n", i, readErr)
			}
			continue
		}
		if content == nil || len(content.Transcript) == 0 {
			continue
		}

		sessionID := content.Metadata.SessionID
		if sessionID == "" {
			fmt.Fprintf(errW, "  Warning: session %d has no session ID, skipping\n", i)
			continue
		}

		// Resolve per-session agent from metadata — skip if agent is unknown
		if content.Metadata.Agent == "" {
			fmt.Fprintf(errW, "  Warning: session %d (%s) has no agent metadata, skipping (cannot determine target directory)\n", i, sessionID)
			continue
		}
		sessionAgent, agErr := ResolveAgentForRewind(content.Metadata.Agent)
		if agErr != nil {
			fmt.Fprintf(errW, "  Warning: session %d (%s) has unknown agent %q, skipping\n", i, sessionID, content.Metadata.Agent)
			continue
		}

		// Compute transcript path from current repo location for cross-machine portability.
		sessionAgentDir, dirErr := sessionAgent.GetSessionDir(repoRoot)
		if dirErr != nil {
			fmt.Fprintf(errW, "  Warning: failed to get session dir for session %d: %v\n", i, dirErr)
			continue
		}
		sessionFile := sessionAgent.ResolveSessionFile(sessionAgentDir, sessionID)

		// Get first prompt for display
		promptPreview := ExtractFirstPrompt(content.Prompts)

		if totalSessions > 1 {
			isLatest := i == totalSessions-1
			if promptPreview != "" {
				if isLatest {
					fmt.Fprintf(w, "  Session %d (latest): %s\n", i+1, promptPreview)
				} else {
					fmt.Fprintf(w, "  Session %d: %s\n", i+1, promptPreview)
				}
			}
			fmt.Fprintf(w, "    Writing to: %s\n", sessionFile)
		} else {
			fmt.Fprintf(w, "Writing transcript to: %s\n", sessionFile)
		}

		// Ensure parent directory exists (session file may be in a different dir than sessionAgentDir)
		if mkdirErr := os.MkdirAll(filepath.Dir(sessionFile), 0o750); mkdirErr != nil {
			fmt.Fprintf(errW, "    Warning: failed to create directory: %v\n", mkdirErr)
			continue
		}

		agentSession := &agent.AgentSession{
			SessionID:  sessionID,
			AgentName:  sessionAgent.Name(),
			RepoPath:   repoRoot,
			SessionRef: sessionFile,
			NativeData: content.Transcript,
		}
		if writeErr := sessionAgent.WriteSession(ctx, agentSession); writeErr != nil {
			if totalSessions > 1 {
				fmt.Fprintf(errW, "    Warning: failed to write session: %v\n", writeErr)
				continue
			}
			return nil, fmt.Errorf("failed to write session: %w", writeErr)
		}

		restored = append(restored, RestoredSession{
			SessionID: sessionID,
			Agent:     sessionAgent.Type(),
			Prompt:    promptPreview,
			CreatedAt: content.Metadata.CreatedAt,
		})
	}

	return restored, nil
}

// ResolveAgentForRewind resolves the agent from checkpoint metadata.
func ResolveAgentForRewind(agentType types.AgentType) (agent.Agent, error) {
	ag, err := agent.GetByAgentType(agentType)
	if err != nil {
		return nil, fmt.Errorf("resolving agent %q: %w", agentType, err)
	}
	return ag, nil
}

// readSessionPrompt reads the first prompt from the session's prompt.txt file stored in git.
// Returns an empty string if the prompt cannot be read.
func readSessionPrompt(repo *git.Repository, commitHash plumbing.Hash, metadataDir string) string {
	// Get the commit and its tree
	commit, err := repo.CommitObject(commitHash)
	if err != nil {
		return ""
	}

	tree, err := commit.Tree()
	if err != nil {
		return ""
	}

	// Look for prompt.txt in the metadata directory
	promptPath := metadataDir + "/" + paths.PromptFileName
	promptEntry, err := tree.File(promptPath)
	if err != nil {
		return ""
	}

	content, err := promptEntry.Contents()
	if err != nil {
		return ""
	}

	return ExtractFirstPrompt(content)
}

// SessionRestoreStatus represents the status of a session being restored.
type SessionRestoreStatus int

const (
	StatusNew             SessionRestoreStatus = iota // Local file doesn't exist
	StatusUnchanged                                   // Local and checkpoint are the same
	StatusCheckpointNewer                             // Checkpoint has newer entries
	StatusLocalNewer                                  // Local has newer entries (conflict)
)

// SessionRestoreInfo contains information about a session being restored.
type SessionRestoreInfo struct {
	SessionID      string
	Prompt         string               // First prompt preview for display
	Status         SessionRestoreStatus // Status of this session
	LocalTime      time.Time
	CheckpointTime time.Time
}

// classifySessionsForRestore checks all sessions in a checkpoint and returns info
// about each session, including whether local logs have newer timestamps.
// repoRoot is used to compute per-session agent directories.
// Sessions without agent metadata are skipped (cannot determine target directory).
func (s *ManualCommitStrategy) classifySessionsForRestore(ctx context.Context, repoRoot string, store committedReader, checkpointID id.CheckpointID, summary *cpkg.CheckpointSummary) []SessionRestoreInfo {
	var sessions []SessionRestoreInfo

	totalSessions := len(summary.Sessions)
	// Check all sessions (0-based indexing)

	// Get worktree root for session directory lookup
	repoRoot, err := paths.WorktreeRoot(ctx)
	if err != nil {
		return fmt.Errorf("failed to get worktree root: %w", err)
	}

	sessionDir, err := ag.GetSessionDir(repoRoot)
	if err != nil {
		return fmt.Errorf("failed to determine session directory: %w", err)
	}

	// Create directory if it doesn't exist
	if err := os.MkdirAll(sessionDir, 0o700); err != nil {
		return fmt.Errorf("failed to create session directory: %w", err)
	}

	// Get strategy and restore sessions using full checkpoint data
	strat := GetStrategy(ctx)

	// Use RestoreLogsOnly via LogsOnlyRestorer interface for multi-session support
	// Create a logs-only rewind point with Agent populated (same as rewind)
	point := strategy.RewindPoint{
		IsLogsOnly:   true,
		CheckpointID: checkpointID,
		Agent:        metadata.Agent,
	}

	sessions, restoreErr := strat.RestoreLogsOnly(ctx, w, errW, point, force)
	if restoreErr != nil || len(sessions) == 0 {
		// Fall back to single-session restore (e.g., old checkpoints without agent metadata)
		return resumeSingleSession(ctx, w, errW, ag, sessionID, checkpointID, repoRoot, force)
	}

	logging.Debug(logCtx, "resume session completed",
		slog.String("checkpoint_id", checkpointID.String()),
		slog.Int("session_count", len(sessions)),
	)

	return displayRestoredSessions(w, sessions)
}

// displayRestoredSessions sorts sessions by CreatedAt and prints resume commands.
func displayRestoredSessions(w io.Writer, sessions []strategy.RestoredSession) error {
	sort.SliceStable(sessions, func(i, j int) bool {
		return sessions[i].CreatedAt.Before(sessions[j].CreatedAt)
	})

	if len(sessions) > 1 {
		fmt.Fprintf(w, "\n✓ Restored %d sessions. To continue, run:\n", len(sessions))
	} else if len(sessions) == 1 {
		fmt.Fprintf(w, "✓ Restored session %s.\n", sessions[0].SessionID)
		fmt.Fprintf(w, "\nTo continue this session, run:\n")
	}

	isMulti := len(sessions) > 1
	for i, sess := range sessions {
		sessionAgent, err := strategy.ResolveAgentForRewind(sess.Agent)
		if err != nil {
			return fmt.Errorf("failed to resolve agent for session %s: %w", sess.SessionID, err)
		}
