	root, relPath, err := openAllowedRoot(dst)
	if err != nil {
		return err
	}
	defer root.Close()

	if err := osroot.WriteFile(root, relPath, input, 0o600); err != nil {
		return fmt.Errorf("failed to write file: %w", err)
	}
	return nil
}

